def lname(tag):
    return tag.split('}',1)[-1] if isinstance(tag,str) and '}' in tag else tag

def kids(el, name=None):
    if el is None: return []
    if name is None: return list(el)
    return [c for c in list(el) if lname(c.tag)==name]

def child(el, name):
    arr=kids(el,name); return arr[0] if arr else None

def ctext(el, name, default=None):
    c=child(el,name)
    if c is None or c.text is None: return default
    return c.text.strip()

def text_of(el, default=''):
    if el is None or el.text is None: return default
    return el.text.strip()

def parse_bool(s):
    return str(s).strip().lower() in ('1','true','yes')

def parse_int(s, default=0):
    if s is None: return default
    if isinstance(s, int): return s
    ss=str(s).strip().replace('_','')
    if ss == '': return default
    # SVD occasionally uses binary x notation; keep this forgiving.
    try:
        return int(ss,0)
    except Exception:
        if ss.lower().endswith('h'):
            try: return int(ss[:-1],16)
            except Exception: return default
        try: return int(float(ss))
        except Exception: return default


def parse_dim_index(s, dim):
    if not s:
        return [str(i) for i in range(dim)], f"0-{dim-1}" if dim else ""
    s=s.strip()
    if ',' in s:
        vals=[x.strip() for x in s.split(',') if x.strip()!='']
        return vals, ','.join(vals)
    m=re.match(r'^\s*(-?\d+)\s*-\s*(-?\d+)\s*$', s)
    if m:
        a,b=int(m.group(1)),int(m.group(2)); step=1 if b>=a else -1
        vals=[str(x) for x in range(a,b+step,step)]
        return vals, f"{a}-{b}"
    return [s], s


def strip_dim_name(name):
    return (name or '').replace('%s','')


def parse_field(fe, reg_access):
    name=ctext(fe,'name','')
    desc=ctext(fe,'description','')
    # bits
    bo=ctext(fe,'bitOffset')
    bw=ctext(fe,'bitWidth')
    if bo is not None and bw is not None:
        offset=parse_int(bo); width=parse_int(bw,1)
    elif ctext(fe,'lsb') is not None and ctext(fe,'msb') is not None:
        offset=parse_int(ctext(fe,'lsb')); width=parse_int(ctext(fe,'msb'))-offset+1
    elif ctext(fe,'bitRange'):
        br=ctext(fe,'bitRange')
        m=re.search(r'\[\s*(\d+)\s*:\s*(\d+)\s*\]', br)
        if m:
            msb=int(m.group(1)); lsb=int(m.group(2)); offset=lsb; width=msb-lsb+1
        else: offset=0; width=1
    else:
        offset=0; width=1
    dim=parse_int(ctext(fe,'dim'),0) if ctext(fe,'dim') else 0
    dim_inc=parse_int(ctext(fe,'dimIncrement'), width) if dim else 0
    dim_indices, dim_index_text = parse_dim_index(ctext(fe,'dimIndex'), dim) if dim else ([], '')
    evs=[]
    for evroot in kids(fe,'enumeratedValues'):
        evname=ctext(evroot,'name')
        values=[]
        for eve in kids(evroot,'enumeratedValue'):
            values.append({'name':ctext(eve,'name',''), 'description':ctext(eve,'description',''), 'value':parse_int(ctext(eve,'value'),0), 'default': parse_bool(ctext(eve,'isDefault','false'))})
        if values:
            evs.append({'name':evname, 'values':values})
    return {
        'name': name, 'description': desc, 'offset': offset, 'width': width,
        'access': ctext(fe,'access', reg_access), 'dim': dim, 'dim_increment': dim_inc,
        'dim_indices': dim_indices, 'dim_index_text': dim_index_text,
        'enumerated': evs[0] if evs else None,
        'modified_write_values': ctext(fe,'modifiedWriteValues')
    }


def parse_register(rege, defaults):
    name=ctext(rege,'name','')
    size_text=ctext(rege,'size')
    size=parse_int(size_text) if size_text is not None else defaults.get('size')
    access=ctext(rege,'access', defaults.get('access') or 'read-write')
    reset_text=ctext(rege,'resetValue')
    reset=parse_int(reset_text) if reset_text is not None else defaults.get('reset')
    reset_present = reset_text is not None or defaults.get('reset_present', False)
    fields=[]
    fs=child(rege,'fields')
    if fs is not None:
        for fe in kids(fs,'field'):
            fields.append(parse_field(fe, access))
    dim=parse_int(ctext(rege,'dim'),0) if ctext(rege,'dim') else 0
    dim_inc=parse_int(ctext(rege,'dimIncrement'), (size or 32)//8) if dim else 0
    dim_indices, dim_index_text = parse_dim_index(ctext(rege,'dimIndex'), dim) if dim else ([], '')
    return {'kind':'register','name':name,'description':ctext(rege,'description',''), 'addressOffset':parse_int(ctext(rege,'addressOffset'),0),
            'size':size, 'access':access, 'reset':reset, 'reset_present':reset_present,
            'fields':fields, 'derivedFrom':rege.attrib.get('derivedFrom'), 'alternateGroup':ctext(rege,'alternateGroup'),
            'dim':dim, 'dimIncrement':dim_inc, 'dim_indices':dim_indices, 'dim_index_text':dim_index_text,
            'modified_write_values':ctext(rege,'modifiedWriteValues')}


def parse_cluster(ce, defaults):
    regs=[]
    cdefs=defaults.copy()
    if ctext(ce,'size') is not None: cdefs['size']=parse_int(ctext(ce,'size'))
    if ctext(ce,'access') is not None: cdefs['access']=ctext(ce,'access')
    if ctext(ce,'resetValue') is not None: cdefs['reset']=parse_int(ctext(ce,'resetValue')); cdefs['reset_present']=True
    for sub in kids(ce):
        if lname(sub.tag)=='register': regs.append(parse_register(sub,cdefs))
        elif lname(sub.tag)=='cluster': regs.append(parse_cluster(sub,cdefs))
    dim=parse_int(ctext(ce,'dim'),0) if ctext(ce,'dim') else 0
    dim_inc=parse_int(ctext(ce,'dimIncrement'),0) if dim else 0
    dim_indices, dim_index_text = parse_dim_index(ctext(ce,'dimIndex'), dim) if dim else ([], '')
    return {'kind':'cluster','name':ctext(ce,'name',''), 'description':ctext(ce,'description',''), 'addressOffset':parse_int(ctext(ce,'addressOffset'),0),
            'registers':regs, 'dim':dim, 'dimIncrement':dim_inc, 'dim_indices':dim_indices, 'dim_index_text':dim_index_text,
            'derivedFrom':ce.attrib.get('derivedFrom')}


def parse_device_xml(data):
    if not data.strip():
        raise ValueError('the document does not have a root node')
    try:
        root=ET.fromstring(data)
    except ET.ParseError as e:
        raise ValueError(str(e))
    if lname(root.tag) != 'device':
        raise ValueError('the document does not have a root node')
    dev={'name':ctext(root,'name',''), 'description':ctext(root,'description',''), 'peripherals':[], 'cpu':{}, 'size':None, 'access':None, 'reset':None, 'reset_present':False}
    if ctext(root,'size') is not None: dev['size']=parse_int(ctext(root,'size'))
    if ctext(root,'access') is not None: dev['access']=ctext(root,'access')
    if ctext(root,'resetValue') is not None: dev['reset']=parse_int(ctext(root,'resetValue')); dev['reset_present']=True
    cpu=child(root,'cpu')
    if cpu is not None:
        if ctext(cpu,'nvicPrioBits') is not None: dev['cpu']['nvicPrioBits']=parse_int(ctext(cpu,'nvicPrioBits'))
        dev['cpu']['name']=ctext(cpu,'name')
    peris=child(root,'peripherals')
    if peris is not None:
        for pe in kids(peris,'peripheral'):
            p={'name':ctext(pe,'name',''), 'description':ctext(pe,'description', ctext(pe,'name','')), 'groupName':ctext(pe,'groupName'),
               'baseAddress':parse_int(ctext(pe,'baseAddress'),0), 'registers':[], 'interrupts':[], 'derivedFrom':pe.attrib.get('derivedFrom')}
            pdefs={'size':dev.get('size'), 'access':dev.get('access'), 'reset':dev.get('reset'), 'reset_present':dev.get('reset_present',False)}
            for k in ('size','access','resetValue'):
                pass
            if ctext(pe,'size') is not None: pdefs['size']=parse_int(ctext(pe,'size'))
            if ctext(pe,'access') is not None: pdefs['access']=ctext(pe,'access')
            if ctext(pe,'resetValue') is not None: pdefs['reset']=parse_int(ctext(pe,'resetValue')); pdefs['reset_present']=True
            regs=child(pe,'registers')
            if regs is not None:
                for sub in kids(regs):
                    if lname(sub.tag)=='register': p['registers'].append(parse_register(sub,pdefs))
                    elif lname(sub.tag)=='cluster': p['registers'].append(parse_cluster(sub,pdefs))
            for ie in kids(pe,'interrupt'):
                p['interrupts'].append({'name':ctext(ie,'name',''), 'description':ctext(ie,'description',''), 'value':parse_int(ctext(ie,'value'),0)})
            dev['peripherals'].append(p)
    return dev


def parse_device_json(data):
    # A permissive tiny JSON front-end for serde-like SVD JSON. It accepts either
    # {"device": {...}} or the device object itself and maps only common fields.
    obj=json.loads(data)
    if isinstance(obj,dict) and 'device' in obj: obj=obj['device']
    # Convert a simple dict to XML-ish by direct recursive extraction is overkill;
    # support a small shape used in tests.
    dev={'name':obj.get('name',''), 'description':obj.get('description',''), 'peripherals':[], 'cpu':obj.get('cpu') or {}, 'size':obj.get('size'), 'access':obj.get('access'), 'reset':obj.get('resetValue'), 'reset_present':'resetValue' in obj}
    pers=obj.get('peripherals',{})
    plist=pers.get('peripheral', pers if isinstance(pers,list) else []) if isinstance(pers,(dict,list)) else []
    if isinstance(plist,dict): plist=[plist]
    for pe in plist:
        p={'name':pe.get('name',''), 'description':pe.get('description',pe.get('name','')), 'groupName':pe.get('groupName'), 'baseAddress':parse_int(pe.get('baseAddress'),0), 'registers':[], 'interrupts':[], 'derivedFrom':pe.get('derivedFrom')}
        regs=(pe.get('registers') or {}).get('register', []) if isinstance(pe.get('registers'),dict) else []
        if isinstance(regs,dict): regs=[regs]
        for r in regs:
            fields=[]; fs=(r.get('fields') or {}).get('field', []) if isinstance(r.get('fields'),dict) else []
            if isinstance(fs,dict): fs=[fs]
            for f in fs:
                fields.append({'name':f.get('name',''), 'description':f.get('description',''), 'offset':parse_int(f.get('bitOffset'),0), 'width':parse_int(f.get('bitWidth'),1), 'access':f.get('access', r.get('access','read-write')), 'dim':0, 'dim_increment':0, 'dim_indices':[], 'dim_index_text':'', 'enumerated':None, 'modified_write_values':f.get('modifiedWriteValues')})
            p['registers'].append({'kind':'register','name':r.get('name',''), 'description':r.get('description',''), 'addressOffset':parse_int(r.get('addressOffset'),0), 'size':parse_int(r.get('size'),32) if r.get('size') is not None else None, 'access':r.get('access','read-write'), 'reset':parse_int(r.get('resetValue'),0), 'reset_present':'resetValue' in r, 'fields':fields, 'derivedFrom':r.get('derivedFrom'), 'alternateGroup':r.get('alternateGroup'), 'dim':0, 'dimIncrement':0, 'dim_indices':[], 'dim_index_text':'', 'modified_write_values':r.get('modifiedWriteValues')})
        ints=pe.get('interrupt',[])
        if isinstance(ints,dict): ints=[ints]
        for it in ints: p['interrupts'].append({'name':it.get('name',''), 'description':it.get('description',''), 'value':parse_int(it.get('value'),0)})
        dev['peripherals'].append(p)
    return dev

# Identifier formatting

def clean_for_ident(name, keep_underscore=True):
    s=strip_dim_name(str(name or ''))
    s=s.replace('-', '')
    s=re.sub(r'[^0-9A-Za-z_]', '_' if keep_underscore else '', s)
    return s

def cap_word(w):
    if not w: return ''
    if w[0].isdigit(): return w[0] + w[1:].lower()
    return w[0].upper() + w[1:].lower()

def pascal(name):
    s=clean_for_ident(name, True)
    trailing=len(s)-len(s.rstrip('_'))
    core=s.rstrip('_')
    parts=[p for p in core.split('_') if p!='']
    res=''.join(cap_word(p) for p in parts)
    res += '_'*trailing
    if res == '': res='_'
    if res[0].isdigit(): res='_'+res
    return res

def snake(name):
    s=clean_for_ident(name, True).lower()
    s=re.sub(r'_+', '_', s)
    if s == '': s='_'
    if s[0].isdigit(): s='_'+s
    if s in RUST_KEYWORDS: s += '_'
    return s

def constant(name):
    s=clean_for_ident(name, True).upper()
    s=re.sub(r'_+', '_', s)
    if s == '': s='_'
    if s[0].isdigit(): s='_'+s
    return s

def unchanged(name):
    s=clean_for_ident(name, True)
    if s == '': s='_'
    if s[0].isdigit(): s='_'+s
    if s in RUST_KEYWORDS: s += '_'
    return s

class Ident:
    def __init__(self, cfg):
        if cfg.get('ident_formats_theme') == 'legacy':
            self.fmts={
                'peripheral':('', '', ''), 'peripheral_spec':('c','','_SPEC'), 'peripheral_mod':('s','',''), 'peripheral_singleton':('', '', ''),
                'register':('', '', ''), 'register_spec':('c','','_SPEC'), 'register_mod':('s','',''), 'register_accessor':('s','',''),
                'field_reader':('c','','_R'), 'field_writer':('c','','_W'), 'field_accessor':('s','',''),
                'enum_name':('p','',''), 'enum_value':('p','',''), 'enum_value_accessor':('s','',''), 'interrupt':('', '', ''),
                'cluster':('p','',''), 'cluster_mod':('s','',''), 'cluster_accessor':('s','',''), 'peripheral_feature':('s','','')}
        else:
            self.fmts={
                'peripheral':('p','',''), 'peripheral_spec':('p','','Spec'), 'peripheral_mod':('s','',''), 'peripheral_singleton':('s','',''),
                'register':('p','',''), 'register_spec':('p','','Spec'), 'register_mod':('s','',''), 'register_accessor':('s','',''),
                'field_reader':('p','','R'), 'field_writer':('p','','W'), 'field_accessor':('s','',''),
                'enum_name':('p','',''), 'enum_value':('p','',''), 'enum_value_accessor':('s','',''), 'interrupt':('', '', ''),
                'cluster':('p','',''), 'cluster_mod':('s','',''), 'cluster_accessor':('s','',''), 'peripheral_feature':('s','','')}
        for spec in cfg.get('ident_formats') or []:
            parts=spec.split(':')
            if len(parts) == 4 and parts[0] in self.fmts and parts[2] in ('','p','c','s'):
                self.fmts[parts[0]]=(parts[2], parts[1], parts[3])
    def apply(self, typ, name):
        case,pre,suf=self.fmts.get(typ,('p','',''))
        if case=='p': base=pascal(name)
        elif case=='s': base=snake(name)
        elif case=='c': base=constant(name)
        else: base=unchanged(strip_dim_name(name))
        out=pre+base+suf
        if out and out[0].isdigit(): out='_'+out
        if typ.endswith('accessor') or typ.endswith('mod') or typ in ('peripheral_singleton','enum_value_accessor','peripheral_feature'):
            if out in RUST_KEYWORDS: out += '_'
        return out


def esc(s):
    return json.dumps(str(s), ensure_ascii=False)

def doc(s):
    return f"#[doc = {esc(s)}]"

def doc_raw(s):
    return f"#[doc = r\"{s}\"]"

def alias_attr(s):
    return f"#[doc (alias = {esc(s)})]"

def fmt_hex_group(n, min_even=False, addr=False):
    n=int(n)
    if n==0: return '0' if addr else '0'
    h=f"{n:x}"
    if addr:
        if len(h)==1: h='0'+h
        elif len(h)==3: h='0'+h
        elif len(h)>4 and len(h)%4: h='0'*(4-len(h)%4)+h
    else:
        if len(h)%2: h='0'+h
        if len(h)>4 and len(h)%4: h='0'*(4-len(h)%4)+h
    if len(h)>4:
        parts=[]
        while h:
            parts.append(h[-4:]); h=h[:-4]
        h='_'.join(reversed(parts))
    return '0x'+h

def fmt_addr(n): return fmt_hex_group(n, addr=True)
def fmt_val(n): return fmt_hex_group(n, addr=False)
def fmt_off(n):
    h=f"{int(n):x}"
    if len(h)%2: h='0'+h
    return '0x'+h

def ux_for_bits(bits):
    bits=int(bits or 32)
    if bits <= 8: return 'u8'
    if bits <= 16: return 'u16'
    if bits <= 32: return 'u32'
    return 'u64'

def access_rw(access):
    a=(access or 'read-write').lower()
    r = 'read' in a or a in ('read-only','read-write','read-writeonce','read-writeonce')
    w = 'write' in a or a in ('write-only','read-write','writeonce','read-writeonce')
    if a == 'read-only': w=False; r=True
    if a == 'write-only': r=False; w=True
    if a in ('read-write','read-writeonce','read-writeonce'): r=True; w=True
    if not r and not w: r=True; w=True
    return r,w

def access_code(access):
    r,w=access_rw(access)
    return 'rw' if r and w else ('r' if r else 'w')

def field_mask(width):
    if width>=64: return None
    return (1<<width)-1

def fmt_mask(width):
    m=field_mask(width)
    if m is None: return None
    if m <= 3: return str(m)
    h=f"{m:x}"
    if len(h)%2: h='0'+h
    return '0x'+h

def read_expr(width, offset, reg_bits=32):
    width=int(width); offset=int(offset)
    if width == reg_bits and offset == 0:
        return 'self . bits'
    if width == 1:
        if offset == 0: return '(self . bits & 1) != 0'
        return f'((self . bits >> {offset}) & 1) != 0'
    mask=fmt_mask(width)
    ux=ux_for_bits(width)
    if offset == 0:
        return f'(self . bits & {mask}) as {ux}'
    return f'((self . bits >> {offset}) & {mask}) as {ux}'


def field_doc_bits(f):
    off=f['offset']; w=f['width']; desc=f.get('description') or ''
    if w==1:
        base=f"Bit {off}"
    else:
        base=f"Bits {off}:{off+w-1}"
    return base + (f" - {desc}" if desc else '')


def render_attrs_item(attrs, item):
    if not attrs: return [item]
    lines=[]
    for a in attrs[:-1]: lines.append(a)
    lines.append(attrs[-1] + ' ' + item)
    return lines


def periph_cfg_attrs(p, cfg, ident):
    attrs=[]
    if cfg.get('feature_group'):
        feat=ident.apply('peripheral_feature', p.get('groupName') or p.get('name'))
        attrs.append(f'#[cfg (feature = {esc(feat)})]')
    if cfg.get('feature_peripheral'):
        feat=ident.apply('peripheral_feature', p.get('name'))
        attrs.append(f'#[cfg (feature = {esc(feat)})]')
    return attrs


def effective_reg_name(r, cfg):
    base=strip_dim_name(r.get('name',''))
    ag=r.get('alternateGroup')
    if ag and not cfg.get('ignore_groups'):
        return f"{ag}_{base}"
    return base


def register_size_bytes(r):
    if r.get('size') is None: return None
    return max(1, int(r['size'])//8)

def cluster_size_bytes(c):
    end=0
    for r in c.get('registers',[]):
        sz = cluster_size_bytes(r) if r.get('kind')=='cluster' else (register_size_bytes(r) or 4)
        if r.get('dim'):
            inc=r.get('dimIncrement') or sz
            span=(r['dim']-1)*inc+sz
        else: span=sz
        end=max(end, int(r.get('addressOffset',0))+span)
    return end or 4


def render_access_sentences(mod, readable, writable, reset, paren=False):
    rlink=f'[`{mod}::R`]' + ('(R)' if paren else '')
    wlink=f'[`{mod}::W`]' + ('(W)' if paren else '')
    parts=[]
    if readable:
        parts.append(f'You can [`read`](crate::Reg::read) this register and get {rlink}.')
    if writable:
        if reset:
            parts.append(f'You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using {wlink}.')
        else:
            parts.append(f'You can [`write_with_zero`](crate::Reg::write_with_zero) this register using {wlink}.')
    if readable and writable:
        parts.append('You can also [`modify`](crate::Reg::modify) this register.')
    return ' '.join(parts) + (' ' if parts else '') + 'See [API](https://docs.rs/svd2rust/#read--modify--write-api).'


def render_enum(f, reg_reset, cfg, ident):
    ev=f.get('enumerated')
    if not ev: return []
    enum_src = f['name'] if (cfg.get('field_names_for_enums') or not ev.get('name')) else ev.get('name')
    enum_name=ident.apply('enum_name', enum_src)
    width=f['width']; lines=[]
    reset_val=0
    if reg_reset is not None:
        reset_val=(int(reg_reset)>>f['offset']) & ((1<<width)-1 if width<64 else 0xffffffffffffffff)
        lines.append(doc(f"{f.get('description','')}\n\nValue on reset: {reset_val}"))
    elif f.get('description'):
        lines.append(doc(f.get('description','')))
    if width==1:
        lines.append('#[derive (Clone , Copy , Debug , PartialEq , Eq)] pub enum ' + enum_name + ' {')
    else:
        lines.append('#[derive (Clone , Copy , Debug , PartialEq , Eq)]')
        lines.append(f'#[repr ({ux_for_bits(width)})] pub enum {enum_name} {{')
    vals=ev.get('values') or []
    var_parts=[]
    for v in vals:
        vi=int(v.get('value',0)); vn=ident.apply('enum_value', v.get('name',''))
        vd=v.get('description') or f'`{vi}`'
        var_parts.append(f'{doc(f"{vi}: {vd}")} {vn} = {vi} ,')
    if var_parts:
        # Join variants on following lines, with closing brace attached to last like quote display.
        lines.extend(var_parts[:-1])
        lines.append(var_parts[-1] + ' }' + ('' if width==1 else f' impl From < {enum_name} > for {ux_for_bits(width)} {{'))
    else:
        lines[-1] += ' }'
    if width==1:
        lines[-1] += f' impl From < {enum_name} > for bool {{'
        lines.append(f'#[inline (always)] fn from (variant : {enum_name}) -> Self {{ variant as u8 != 0 }} }}')
    else:
        lines.append(f'#[inline (always)] fn from (variant : {enum_name}) -> Self {{ variant as _ }} }} impl crate :: FieldSpec for {enum_name} {{ type Ux = {ux_for_bits(width)} ; }} impl crate :: IsEnum for {enum_name} {{ }}')
    return lines


def enum_name_for_field(f, cfg, ident):
    ev=f.get('enumerated')
    if not ev: return None
    src=f['name'] if (cfg.get('field_names_for_enums') or not ev.get('name')) else ev.get('name')
    return ident.apply('enum_name', src)


def render_field_aliases(f, readable, writable, cfg, ident):
    lines=[]; name=f['name']; desc=f.get('description') or ''
    fr=ident.apply('field_reader', strip_dim_name(name)); fw=ident.apply('field_writer', strip_dim_name(name))
    enum_name=enum_name_for_field(f,cfg,ident)
    if readable:
        if f['width']==1:
            ty='crate :: BitReader' + (f' < {enum_name} >' if enum_name else '')
        else:
            if enum_name: ty=f'crate :: FieldReader < {enum_name} >'
            else:
                ux=ux_for_bits(f['width']); ty='crate :: FieldReader' + (f' < {ux} >' if ux!='u8' else '')
        lines.append(f'{doc(f"Field `{name}` reader - {desc}")} pub type {fr} = {ty} ;')
    if writable:
        mwv=f.get('modified_write_values')
        writer_kind='BitWriter'
        if mwv:
            mapping={'oneToClear':'BitWriter1C','oneToSet':'BitWriter1S','zeroToClear':'BitWriter0C','zeroToSet':'BitWriter0S','oneToToggle':'BitWriter1T','zeroToToggle':'BitWriter0T'}
            writer_kind=mapping.get(mwv, 'BitWriter')
        if f['width']==1:
            ty=f'crate :: {writer_kind} < \'a , REG' + (f' , {enum_name}' if enum_name else '') + ' >'
        else:
            ux=ux_for_bits(f['width']); extra=''
            if enum_name: extra=f' , {enum_name}'
            elif ux!='u8': extra=f' , {ux}'
            ty=f'crate :: FieldWriter < \'a , REG , {f["width"]}{extra} >'
        lines.append(f'{doc(f"Field `{name}` writer - {desc}")} pub type {fw} < \'a , REG > = {ty} ;')
    return lines


def render_field_methods(fields, readable, writable, reg_spec, reg_bits, cfg, ident):
    lines=[]
    rfields=[]; wfields=[]
    for f in fields:
        fr=ident.apply('field_reader', strip_dim_name(f['name'])); fw=ident.apply('field_writer', strip_dim_name(f['name']))
        accessor=ident.apply('field_accessor', strip_dim_name(f['name']))
        r,w=access_rw(f.get('access'))
        if readable and r:
            rfields.append((f,fr,accessor))
        if writable and w:
            wfields.append((f,fw,accessor))
    if readable:
        lines.append('impl R {')
        for f,fr,accessor in rfields:
            if f.get('dim'):
                # compact indexed field-array support
                base=accessor.replace('%s','')
                lines.append(doc(f"{('Bit' if f['width']==1 else 'Field')} ({f.get('dim_index_text')})"))
                lines.append(f'#[inline (always)] pub fn {base} (& self , n : u8) -> {fr} {{ #[allow (clippy :: no_effect)] [() ; {f["dim"]}] [n as usize] ; {fr} :: new ((self . bits >> (n * {f["dim_increment"]} + {f["offset"]})) as _) }}')
                continue
            lines.append(doc(field_doc_bits(f)))
            expr=read_expr(f['width'], f['offset'], reg_bits)
            lines.append(f'#[inline (always)] pub fn {accessor} (& self) -> {fr} {{ {fr} :: new ({expr}) }}')
        lines.append('}')
        if cfg.get('impl_debug') and rfields:
            body=' '.join([f'. field ({esc(acc)} , & self . {acc} ())' for _,_,acc in rfields])
            impl=f'impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ f . debug_struct ({esc(reg_spec[:-4] if reg_spec.endswith("Spec") else reg_spec)}) {body} . finish () }} }}'
            if cfg.get('impl_debug_feature'):
                impl=f'#[cfg (feature = {esc(cfg["impl_debug_feature"])})] '+impl
            lines[-1] += ' ' + impl
    if writable:
        if lines and lines[-1] == '}': lines[-1] += ' impl W {'
        else: lines.append('impl W {')
        for f,fw,accessor in wfields:
            lines.append(doc(field_doc_bits(f)))
            lines.append(f'#[inline (always)] pub fn {accessor} (& mut self) -> {fw} < \'_ , {reg_spec} > {{ {fw} :: new (self , {f["offset"]}) }}')
        lines.append('}')
    return lines


def render_register(r, cfg, ident, in_cluster=False):
    lines=[]
    eff=effective_reg_name(r,cfg)
    reg_type=ident.apply('register', eff)
    reg_mod=ident.apply('register_mod', eff)
    reg_spec=ident.apply('register_spec', eff)
    doc_name=eff
    inner_name=r.get('name','')
    desc=r.get('description') or ''
    readable,writable=access_rw(r.get('access'))
    reset_present=r.get('reset_present', False)
    sent=render_access_sentences(reg_mod, readable, writable, reset_present, paren=False)
    accessor_doc=f"{doc_name} ({access_code(r.get('access'))}) register accessor: {desc}\n\n{sent}\n\nFor information about available fields see [`mod@{reg_mod}`] module"
    prefix=doc(accessor_doc)
    alias = alias_attr(doc_name) + ' ' if reg_type != doc_name else ''
    lines.append(f'{prefix} {alias}pub type {reg_type} = crate :: Reg < {reg_mod} :: {reg_spec} > ;')
    lines.append(f'{doc(desc)} pub mod {reg_mod} {{')
    if readable:
        lines.append(f'{doc(f"Register `{inner_name}` reader")} pub type R = crate :: R < {reg_spec} > ;')
    if writable:
        lines.append(f'{doc(f"Register `{inner_name}` writer")} pub type W = crate :: W < {reg_spec} > ;')
    fields=r.get('fields') or []
    # enum and field type aliases
    for f in fields:
        fr,fw=access_rw(f.get('access'))
        lines.extend(render_enum(f, r.get('reset') if reset_present else None, cfg, ident))
        lines.extend(render_field_aliases(f, readable and fr, writable and fw, cfg, ident))
    if fields:
        lines.extend(render_field_methods(fields, readable, writable, reg_spec, int(r.get('size') or 32), cfg, ident))
    else:
        # quote-style raw Debug for empty readable registers and empty writer impls
        if readable:
            if lines and lines[-1].endswith(';'):
                lines[-1] += ' impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , "{}" , self . bits ()) } }'
            else:
                lines.append('impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , "{}" , self . bits ()) } }')
        elif writable:
            lines.append(f'impl core :: fmt :: Debug for crate :: generic :: Reg < {reg_spec} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < \'_ >) -> core :: fmt :: Result {{ write ! (f , "(not readable)") }} }}')
        if writable:
            if lines and 'impl core :: fmt :: Debug' in lines[-1]: lines[-1] += ' impl W { }'
            elif lines and lines[-1].endswith(';'): lines[-1] += ' impl W { }'
            else: lines.append('impl W { }')
    spec_doc=f"{desc}\n\n{render_access_sentences(reg_mod, readable, writable, reset_present, paren=True)}"
    ux=ux_for_bits(r.get('size') or 32)
    lines.append(f'{doc(spec_doc)} pub struct {reg_spec} ; impl crate :: RegisterSpec for {reg_spec} {{ type Ux = {ux} ; }}')
    if readable:
        lines.append(f'{doc(f"`read()` method returns [`{reg_mod}::R`](R) reader structure")} impl crate :: Readable for {reg_spec} {{ }}')
    if writable:
        # modified write values bitmaps
        one=0; zero=0
        for f in fields:
            mw=f.get('modified_write_values')
            if not mw: continue
            mask=((1<<f['width'])-1) << f['offset']
            if mw.startswith('oneTo'): one |= mask
            if mw.startswith('zeroTo'): zero |= mask
        extra=''
        if zero: extra += f' const ZERO_TO_MODIFY_FIELDS_BITMAP : {ux} = {fmt_val(zero)} ;'
        if one: extra += f' const ONE_TO_MODIFY_FIELDS_BITMAP : {ux} = {fmt_val(one)} ;'
        lines.append(f'{doc(f"`write(|w| ..)` method takes [`{reg_mod}::W`](W) writer structure")} impl crate :: Writable for {reg_spec} {{ type Safety = crate :: Unsafe ;{extra} }}')
    if reset_present:
        rv=int(r.get('reset') or 0)
        if rv==0:
            lines.append(f'{doc(f"`reset()` method sets {inner_name} to value 0")} impl crate :: Resettable for {reg_spec} {{ }}')
        else:
            lines.append(f'{doc(f"`reset()` method sets {inner_name} to value {fmt_val(rv)}")} impl crate :: Resettable for {reg_spec} {{ const RESET_VALUE : {ux} = {fmt_val(rv)} ; }}')
    lines.append('}')
    return lines


def render_cluster(c, cfg, ident):
    lines=[]
    name=strip_dim_name(c.get('name',''))
    ctype=ident.apply('cluster', name); cmod=ident.apply('cluster_mod', name)
    desc=c.get('description') or ''
    lines.append(f'{doc(desc)} pub use self :: {cmod} :: {ctype} ;')
    lines.append(doc_raw('Cluster'))
    lines.append(f'{doc(desc)} pub mod {cmod} {{')
    lines.append('#[repr (C)]')
    lines.append(f'{doc(desc)} {alias_attr(name) if ctype != name else ""} pub struct {ctype} {{ ' + render_block_fields(c.get('registers',[]), cfg, ident)[0] + ' } impl ' + ctype + ' {')
    for l in render_block_fields(c.get('registers',[]), cfg, ident)[1]: lines.append(l)
    lines.append('}')
    for r in c.get('registers',[]):
        if r.get('kind')=='register': lines.extend(render_register(r,cfg,ident,True))
    lines.append('}')
    return lines


def render_block_fields(items, cfg, ident):
    sorted_items=sorted(items, key=lambda x:int(x.get('addressOffset',0)))
    fields=[]; access=[]; cur=0; resno=1
    for it in sorted_items:
        off=int(it.get('addressOffset',0))
        if off>cur:
            fields.append(f'_reserved{resno} : [u8 ; {fmt_off(off-cur)}] ,'); resno+=1; cur=off
        if it.get('kind')=='cluster':
            base=strip_dim_name(it.get('name',''))
            ty=ident.apply('cluster', base); acc=ident.apply('cluster_accessor', base)
            sz=cluster_size_bytes(it)
            dim=it.get('dim') or 0
            if dim and not cfg.get('keep_list'):
                fields.append(f'{acc} : () ,')
                rng=f'{fmt_off(off)}..{fmt_off(off+sz*dim)}'
                access.append(doc(f'{rng} - {it.get("description") or ""}'))
                access.append(doc(''))
                first=(it.get('dim_indices') or ['0'])[0]
                access.append(doc(f'<div class="warning">`n` is the index of cluster in the array. `n == 0` corresponds to `{strip_dim_name(it.get("name",""))+first}` cluster.</div>'))
                access.append(f'#[inline (always)] pub const fn {acc} (& self , n : usize) -> & {ty} {{')
                access.append(f'#[allow (clippy :: no_effect)] [() ; {dim}] [n] ; unsafe {{ & * core :: ptr :: from_ref (self) . cast :: < u8 > () . add ({off}) . add ({it.get("dimIncrement") or sz} * n) . cast () }} }}')
                cur=off
            else:
                fields.append(f'{acc} : {ty} ,'); cur=off+sz
                access.append(doc(f'{fmt_off(off)}..{fmt_off(off+sz)} - {it.get("description") or ""}'))
                access.append(f'#[inline (always)] pub const fn {acc} (& self) -> & {ty} {{ & self . {acc} }}')
            continue
        # register
        eff=effective_reg_name(it,cfg); ty=ident.apply('register', eff); acc=ident.apply('register_accessor', eff)
        sz=register_size_bytes(it) or 4
        dim=it.get('dim') or 0
        if dim and cfg.get('keep_list'):
            indices=it.get('dim_indices') or [str(i) for i in range(dim)]
            inc=it.get('dimIncrement') or sz
            for idx_i,idx in enumerate(indices[:dim]):
                nm=it.get('name','').replace('%s', idx); eff2=effective_reg_name({**it,'name':nm,'alternateGroup':it.get('alternateGroup')},cfg)
                acc2=ident.apply('register_accessor', eff2)
                fields.append(f'{acc2} : {ty} ,')
                access.append(doc(f'{fmt_off(off+idx_i*inc)} - {(it.get("description") or "").replace("%s", idx)}'))
                access.append(f'#[inline (always)] pub const fn {acc2} (& self) -> & {ty} {{ & self . {acc2} }}')
            cur=off+inc*dim
        elif dim:
            inc=it.get('dimIncrement') or sz
            if inc==sz:
                fields.append(f'{acc} : [{ty} ; {dim}] ,'); cur=off+inc*dim
                rng=f'{fmt_off(off)}..{fmt_off(off+sz*dim)}'
                access.append(doc(f'{rng} - {it.get("description") or ""}'))
                access.append(f'#[inline (always)] pub const fn {acc} (& self , n : usize) -> & {ty} {{ & self . {acc} [n] }}')
                access.append(doc('Iterator for array of:'))
                access.append(doc(f'{rng} - {it.get("description") or ""}'))
                access.append(f'#[inline (always)] pub fn {acc}_iter (& self) -> impl Iterator < Item = & {ty} > {{ self . {acc} . iter () }}')
            else:
                fields.append(f'{acc} : () ,'); cur=off
                rng=f'{fmt_off(off)}..{fmt_off(off+sz*dim)}'
                access.append(doc(f'{rng} - {it.get("description") or ""}'))
                access.append(doc(''))
                first=(it.get('dim_indices') or ['0'])[0]
                access.append(doc(f'<div class="warning">`n` is the index of register in the array. `n == 0` corresponds to `{it.get("name","").replace("%s", first)}` register.</div>'))
                access.append(f'#[inline (always)] pub const fn {acc} (& self , n : usize) -> & {ty} {{')
                access.append(f'#[allow (clippy :: no_effect)] [() ; {dim}] [n] ; unsafe {{ & * core :: ptr :: from_ref (self) . cast :: < u8 > () . add ({off}) . add ({inc} * n) . cast () }} }}')
                access.append(doc('Iterator for array of:'))
                access.append(doc(f'{rng} - {it.get("description") or ""}'))
                access.append(f'#[inline (always)] pub fn {acc}_iter (& self) -> impl Iterator < Item = & {ty} > {{ (0 .. {dim}) . map (move | n | unsafe {{ & * core :: ptr :: from_ref (self) . cast :: < u8 > () . add ({off}) . add ({inc} * n) . cast () }}) }}')
                for idx_i,idx in enumerate((it.get('dim_indices') or [])[:dim]):
                    nm=it.get('name','').replace('%s',idx); acc2=ident.apply('register_accessor', nm)
                    access.append(doc(f'{fmt_off(off+idx_i*inc)} - {(it.get("description") or "").replace("%s",idx)}'))
                    access.append(f'#[inline (always)] pub const fn {acc2} (& self) -> & {ty} {{ self . {acc} ({idx_i}) }}')
        else:
            fields.append(f'{acc} : {ty} ,'); cur=off+sz
            access.append(doc(f'{fmt_off(off)} - {it.get("description") or ""}'))
            access.append(f'#[inline (always)] pub const fn {acc} (& self) -> & {ty} {{ & self . {acc} }}')
    return ' '.join(fields), access


def render_peripheral(p, cfg, ident, base_periph=None):
    lines=[]; name=p['name']; desc=p.get('description') or name
    ptype=ident.apply('peripheral', name); pspec=ident.apply('peripheral_spec', name); pmod=ident.apply('peripheral_mod', name)
    attrs=periph_cfg_attrs(p,cfg,ident)
    if base_periph is not None:
        base_mod=ident.apply('peripheral_mod', base_periph['name'])
        lines.append(doc(desc))
        item=f'pub type {ptype} = crate :: Periph < {pspec} > ;'
        lines.extend(render_attrs_item(attrs,item))
        lines.extend(render_attrs_item(attrs,f'pub struct {pspec} ;'))
        lines.extend(render_attrs_item(attrs,f'impl crate :: PeripheralSpec for {pspec} {{ type RB = {base_mod} :: RegisterBlock ; const ADDRESS : usize = {fmt_addr(int(p.get("baseAddress",0))+cfg.get("base_address_shift",0))} ; const NAME : & \'static str = {esc(ptype)} ; }}'))
        lines.append(doc(desc))
        lines.extend(render_attrs_item(attrs,f'pub use self :: {base_mod} as {pmod} ;'))
        return lines
    top=f'pub type {ptype} = crate :: Periph < {pspec} > ; pub struct {pspec} ; impl crate :: PeripheralSpec for {pspec} {{ type RB = {pmod} :: RegisterBlock ; const ADDRESS : usize = {fmt_addr(int(p.get("baseAddress",0))+cfg.get("base_address_shift",0))} ; const NAME : & \'static str = {esc(ptype)} ; }}'
    if attrs:
        lines.append(doc(desc)); lines.extend(render_attrs_item(attrs, f'pub type {ptype} = crate :: Periph < {pspec} > ;'))
        lines.extend(render_attrs_item(attrs, f'pub struct {pspec} ;'))
        lines.extend(render_attrs_item(attrs, f'impl crate :: PeripheralSpec for {pspec} {{ type RB = {pmod} :: RegisterBlock ; const ADDRESS : usize = {fmt_addr(int(p.get("baseAddress",0))+cfg.get("base_address_shift",0))} ; const NAME : & \'static str = {esc(ptype)} ; }}'))
        lines.append(doc(desc)); lines.extend(render_attrs_item(attrs, f'pub mod {pmod} {{'))
    else:
        lines.append(f'{doc(desc)} {top}')
        lines.append(f'{doc(desc)} pub mod {pmod} {{')
    lines.append('#[repr (C)]')
    if cfg.get('impl_debug'): lines.append('#[derive (Debug)]')
    fields_str, access_lines=render_block_fields(p.get('registers',[]), cfg, ident)
    lines.append(f'{doc("Register block")} pub struct RegisterBlock {{ {fields_str} }} impl RegisterBlock {{')
    lines.extend(access_lines)
    lines.append('}')
    # render register/cluster modules and aliases for derived regs
    base_regs={}
    derived_aliases=[]
    for r in p.get('registers',[]):
        if r.get('kind')=='register':
            if r.get('derivedFrom'):
                # Emit a compact alias if base is known; otherwise render normally.
                bname=strip_dim_name(r.get('derivedFrom').split('.')[-1])
                if bname in base_regs:
                    beff=effective_reg_name(base_regs[bname],cfg); deff=effective_reg_name(r,cfg)
                    derived_aliases.append(f'pub use {ident.apply("register",beff)} as {ident.apply("register",deff)} ; pub use {ident.apply("register_mod",beff)} as {ident.apply("register_mod",deff)} ;')
                    continue
            base_regs[strip_dim_name(r.get('name',''))]=r
            lines.extend(render_register(r,cfg,ident))
        elif r.get('kind')=='cluster':
            lines.extend(render_cluster(r,cfg,ident))
    lines.extend(derived_aliases)
    lines.append('}')
    return lines


def collect_interrupts(dev):
    ints=[]; seen=set()
    for p in dev.get('peripherals',[]):
        for it in p.get('interrupts',[]):
            key=(it.get('name'), int(it.get('value',0)))
            if key not in seen:
                seen.add(key); ints.append(it)
    ints.sort(key=lambda x:(int(x.get('value',0)), x.get('name','')))
    return ints


def render_interrupts(ints, cfg):
    target=cfg.get('target'); ed24=cfg.get('edition')=='2024'; lines=[]
    if target in ('none','mips'):
        if not ints: return []
        lines.append('#[doc (hidden)] pub mod interrupt {')
        lines.append(doc_raw('Enumeration of all the interrupts.'))
        lines.append('#[derive (Copy , Clone , Debug , PartialEq , Eq)]')
        lines.append('#[repr (u16)] pub enum Interrupt {')
        for it in ints: lines.append(f'{doc(f"{int(it["value"])} - {it.get("description") or ""}")} {it["name"]} = {int(it["value"])} ,')
        vals=' '.join([f'{int(it["value"])} => Ok (Interrupt :: {it["name"]}) ,' for it in ints])
        lines.append('}')
        lines.append(doc_raw(' TryFromInterruptError'))
        lines.append(f'#[derive (Debug , Copy , Clone)] pub struct TryFromInterruptError (()) ; impl Interrupt {{')
        lines.append(doc_raw(' Attempt to convert a given value into an `Interrupt`'))
        lines.append(f'#[inline] pub fn try_from (value : u8) -> Result < Self , TryFromInterruptError > {{ match value {{ {vals} _ => Err (TryFromInterruptError (())) , }} }} }} }} pub use self :: interrupt :: Interrupt ;')
        return lines
    if target in ('cortex-m','msp430','riscv','xtensa-lx'):
        names=' '.join([f'fn {it["name"]} () ;' for it in ints])
        if target != 'msp430':
            lines.append(f'#[cfg (feature = "rt")] {"unsafe " if ed24 else ""}extern "C" {{ {names} }}')
        else:
            lines.append(f'#[cfg (feature = "rt")] extern "C" {{ {names} }}')
        lines.append('#[doc (hidden)]')
        if target=='riscv': lines.append('#[repr (C)] pub union Vector { pub _handler : unsafe extern "C" fn () , pub _reserved : usize , }')
        elif target=='xtensa-lx': lines.append('#[repr (C)] pub union Vector { pub _handler : unsafe extern "C" fn () , _reserved : u32 , }')
        else: lines.append('#[repr (C)] pub union Vector { _handler : unsafe extern "C" fn () , _reserved : u32 , }')
        lines.append('#[cfg (feature = "rt")]')
        lines.append('#[doc (hidden)]')
        if target=='msp430':
            lines.append('#[link_section = "__interrupt_vector_0"]' if not ed24 else '#[unsafe (link_section = "__interrupt_vector_0")]')
            attr='#[used]'
        else:
            lines.append('#[unsafe (link_section = ".vector_table.interrupts")]' if ed24 else '#[link_section = ".vector_table.interrupts"]')
            attr='#[unsafe (no_mangle)]' if ed24 else '#[no_mangle]'
        n=(max([int(it['value']) for it in ints]) + 1) if ints else 0
        by={int(it['value']):it for it in ints}
        elems=[]
        for i in range(n):
            if i in by: elems.append(f'Vector {{ _handler : {by[i]["name"]} }}')
            else: elems.append('Vector { _reserved : 0 }')
        arr=' , '.join(elems)
        if elems: arr += ' ,'
        lines.append(f'{attr} pub static __INTERRUPTS : [Vector ; {n}] = [{arr}] ;')
        lines.append(doc_raw('Enumeration of all the interrupts.'))
        if ints:
            lines.append('#[derive (Copy , Clone , Debug , PartialEq , Eq)]')
            lines.append('#[repr (u16)] pub enum Interrupt {')
            for it in ints: lines.append(f'{doc(f"{int(it["value"])} - {it.get("description") or ""}")} {it["name"]} = {int(it["value"])} ,')
            trait='cortex_m :: interrupt :: InterruptNumber' if target=='cortex-m' else ('msp430 :: interrupt :: InterruptNumber' if target=='msp430' else '')
            if trait:
                lines.append(f'}} unsafe impl {trait} for Interrupt {{')
                lines.append('#[inline (always)] fn number (self) -> u16 { self as u16 } }')
            else:
                lines.append('}')
        else:
            trait='cortex_m :: interrupt :: InterruptNumber' if target=='cortex-m' else ('msp430 :: interrupt :: InterruptNumber' if target=='msp430' else '')
            if trait:
                lines.append(f'#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt {{ }} unsafe impl {trait} for Interrupt {{')
                lines.append('#[inline (always)] fn number (self) -> u16 { match self { } } }')
            else:
                lines.append('#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { }')
        return lines
    return []


def header_line(devname, cfg):
    if cfg.get('skip_crate_attributes'):
        return None
    h=f'Peripheral access API for {devname} microcontrollers (generated using svd2rust v0.37.1 (e29353d 2026-03-03))\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust'
    if cfg.get('make_mod'):
        return f'# ! [doc = {esc(h)}]'
    return f'# ! [doc = {esc(h)}] # ! [allow (non_camel_case_types)] # ! [allow (non_snake_case)] # ! [no_std] # ! [cfg_attr (docsrs , feature (doc_cfg))]'


def render_lib(dev, cfg, log):
    ident=Ident(cfg); lines=[]
    h=header_line(dev.get('name',''), cfg)
    top_extras=[]
    if dev.get('cpu',{}).get('nvicPrioBits') is not None and cfg.get('target')=='cortex-m':
        top_extras.append(f'{doc_raw("Number available in the NVIC for configuring priority")} pub const NVIC_PRIO_BITS : u8 = {int(dev["cpu"]["nvicPrioBits"])} ;')
    if cfg.get('reexport_core_peripherals') and cfg.get('target')=='cortex-m':
        top_extras.append('pub use cortex_m :: peripheral :: Peripherals as CorePeripherals ; pub use cortex_m :: peripheral :: { CBP , CPUID , DCB , DWT , FPB , FPU , ITM , MPU , NVIC , SCB , SYST , TPIU , } ;')
    if h is not None:
        if top_extras and not (dev.get('cpu',{}).get('nvicPrioBits') is not None):
            lines.append(h + ' ' + ' '.join(top_extras)); top_extras=[]
        else: lines.append(h)
    if top_extras: lines.append(' '.join(top_extras))
    if cfg.get('reexport_interrupt') and cfg.get('target')=='cortex-m':
        lines.append('#[cfg (feature = "rt")] pub use cortex_m_rt :: interrupt ;')
        lines.append('#[cfg (feature = "rt")] pub use self :: Interrupt as interrupt ;')
    lines.append('#[allow (unused_imports)] use generic :: * ;' if not cfg.get('skip_crate_attributes') else '# [allow (unused_imports)] use generic :: * ;')
    if cfg.get('generic_mod'):
        lines.append('#[doc = "Common register and bit access and modify traits"] pub mod generic ;')
    else:
        lines.append((GENERIC_INLINE_ATOMIC if cfg.get('atomics') else GENERIC_INLINE).rstrip('\n'))
    ints=collect_interrupts(dev)
    lines.extend(render_interrupts(ints,cfg))
    # peripherals
    bases={p['name']:p for p in dev.get('peripherals',[]) if p.get('registers')}
    generated=[]
    for p in dev.get('peripherals',[]):
        base=None
        if p.get('derivedFrom'):
            base=bases.get(p['derivedFrom'].split('.')[-1])
            if not base: continue
        elif not p.get('registers'):
            continue
        generated.append((p,base))
        lines.extend(render_peripheral(p,cfg,ident,base))
    # Peripherals singleton
    nm_attr='#[unsafe (no_mangle)]' if cfg.get('edition')=='2024' else '#[no_mangle]'
    lines.append(f'{nm_attr} static mut DEVICE_PERIPHERALS : bool = false ;')
    lines.append(doc_raw(' All the peripherals.'))
    lines.append('#[allow (non_snake_case)] pub struct Peripherals {')
    field_lines=[]; steal_parts=[]
    for p,base in generated:
        singleton=ident.apply('peripheral_singleton', p['name']); ptype=ident.apply('peripheral', p['name'])
        attrs=periph_cfg_attrs(p,cfg,ident)
        entry=f'{doc(p["name"])} pub {singleton} : {ptype} ,'
        if attrs:
            for a in attrs: field_lines.append(a)
        field_lines.append(entry)
        sp=f'{singleton} : ' + (f'unsafe {{ {ptype} :: steal () }}' if cfg.get('edition')=='2024' else f'{ptype} :: steal ()') + ' ,'
        if attrs:
            for a in attrs: steal_parts.append(a)
        steal_parts.append(sp)
    if field_lines:
        lines.extend(field_lines[:-1])
        lines.append(field_lines[-1] + ' } impl Peripherals {')
    else:
        lines[-1] += ' } impl Peripherals {'
    lines.append(doc_raw(' Returns all the peripherals *once*.'))
    lines.append('#[cfg (feature = "critical-section")]')
    lines.append('#[inline] pub fn take () -> Option < Self > { critical_section :: with (| _ | { if unsafe { DEVICE_PERIPHERALS } { return None } Some (unsafe { Peripherals :: steal () }) }) }')
    lines.append(doc_raw(' Unchecked version of `Peripherals::take`.'))
    lines.append(doc_raw(''))
    lines.append(doc_raw(' # Safety'))
    lines.append(doc_raw(''))
    lines.append(doc_raw(' Each of the returned peripherals must be used at most once.'))
    if cfg.get('edition')=='2024':
        setpart='unsafe { DEVICE_PERIPHERALS = true }'
    else:
        setpart='DEVICE_PERIPHERALS = true ;'
    if steal_parts:
        body=' '.join(steal_parts)
        if cfg.get('edition')=='2024':
            lines.append(f'#[inline] pub unsafe fn steal () -> Self {{ {setpart} Peripherals {{ {body} }} }} }}')
        else:
            lines.append(f'#[inline] pub unsafe fn steal () -> Self {{ {setpart} Peripherals {{ {body} }} }} }}')
    else:
        lines.append(f'#[inline] pub unsafe fn steal () -> Self {{ {setpart} Peripherals {{ }} }} }}')
    return '\n'.join(lines) + '\n'


def validate_render(dev, cfg):
    for p in dev.get('peripherals',[]):
        for r in p.get('registers',[]):
            stack=[r]
            while stack:
                x=stack.pop()
                if x.get('kind')=='cluster': stack.extend(x.get('registers',[])); continue
                if x.get('size') is None:
                    group=p.get('groupName') or 'No group name'
                    return f"0: can't render peripheral '{p.get('name')}', group '{group}'\n        1: can't render register '{x.get('name')}'\n        2: Register {x.get('name')} has no `size` field"
    return None


def write_outputs(dev, cfg, log):
    out=cfg.get('output_dir') or '.'
    main='mod.rs' if cfg.get('make_mod') else 'lib.rs'
    content=render_lib(dev,cfg,log)
    try:
        with open(os.path.join(out,main),'w') as f: f.write(content)
        if cfg.get('generic_mod'):
            with open(os.path.join(out,'generic.rs'),'w') as f: f.write(GENERIC_PRETTY_ATOMIC if cfg.get('atomics') else GENERIC_PRETTY)
        if cfg.get('target') in ('cortex-m','msp430','riscv','xtensa-lx'):
            with open(os.path.join(out,'build.rs'),'w') as f: f.write(BUILD_RS)
            ints=collect_interrupts(dev)
            with open(os.path.join(out,'device.x'),'w') as f:
                for it in ints:
                    f.write(f'PROVIDE({it["name"]} = DefaultHandler);\n')
                f.write('\n')
    except OSError as e:
        sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/main.rs:361:54:\nCouldn't create output file: Os {{ code: {getattr(e,'errno',0)}, kind: {e.__class__.__name__}, message: {json.dumps(e.strerror or str(e))} }}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        return 101
    return 0


def source_type_for(cfg):
    inp=cfg.get('input')
    if inp:
        low=inp.lower()
        if low.endswith('.json'): return 'json'
        if low.endswith('.yaml') or low.endswith('.yml'): return 'yaml'
        return 'xml'
    return cfg.get('source_type') or 'xml'


def main(argv):
    cfg, early = parse_args(argv)
    if early is not None: return early
    log=Logger(cfg.get('log'))
    if cfg.get('target')=='riscv' and not cfg.get('settings'):
        # warnings are emitted during rendering in the original, after parse info.
        pass
    # read input
    try:
        if cfg.get('input'):
            with open(cfg['input'],'r',encoding='utf-8') as f: data=f.read()
        else:
            data=sys.stdin.read()
    except OSError as e:
        return err_block('Cannot open the SVD file', f'{e.strerror} (os error {e.errno})')
    st=source_type_for(cfg)
    log.info('Parsing device from SVD file')
    try:
        if st=='xml': dev=parse_device_xml(data)
        elif st=='json': dev=parse_device_json(data)
        else:
            # No YAML parser dependency; accept a JSON-compatible YAML subset.
            try: dev=parse_device_json(data)
            except Exception as e: raise ValueError(str(e))
    except json.JSONDecodeError as e:
        return err_block('Error parsing SVD JSON file', f'expected value at line {e.lineno} column {e.colno}')
    except Exception as e:
        return err_block(f'Error parsing SVD {st.upper() if st!="xml" else "XML"} file', str(e))
    log.info('Rendering device')
    if cfg.get('target')=='riscv' and not cfg.get('settings'):
        log.warn('No settings file provided for RISC-V target. Using legacy interrupts rendering', 'svd2rust::generate::device')
        log.warn('Please, consider migrating your PAC to riscv 0.12.0 or later', 'svd2rust::generate::device')
    verr=validate_render(dev,cfg)
    if verr:
        return err_block('Error rendering device', verr)
    # Missing description warnings, roughly matching the visible target.
    for p in dev.get('peripherals',[]):
        for r in p.get('registers',[]):
            if r.get('kind')=='register' and not r.get('description'):
                log.warn(f'Missing description for register {r.get("name")}', 'svd2rust::generate::register')
    return write_outputs(dev,cfg,log)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
