        else:
            fields.append(f'{acc} : {ty} ,'); cur=off+sz
            access.append(doc(f'{fmt_off(off)} - {it.get("description") or ""}'))
            access.append(f'#[inline (always)] pub const fn {acc} (& self) -> & {ty} {{ & self . {acc} }}')
